query_document:
query SupplementalR2RepositoryIssues($owner: String!, $name: String!, $after: String) {
  repository(owner: $owner, name: $name) {
    issues(
      first: 100,
      after: $after,
      states: [CLOSED],
      orderBy: {field: CREATED_AT, direction: DESC}
    ) {
      totalCount
      pageInfo { hasNextPage endCursor }
      nodes {
        __typename
        id
        number
        url
        state
        title
        bodyText
        createdAt
        updatedAt
        closedAt
        labels(first: 100) {
          pageInfo { hasNextPage endCursor }
          nodes { name }
        }
      }
    }
  }
}
